/**
 * Dual-audience supplement education library (230 original paraphrased sheets).
 * Data generated by scripts/generate-education-library.mjs — OCR prose is not stored.
 */

import libraryData from "@/data/education-library.json";

export type LibrarySection = {
  heading: string;
  body: string;
};

export type LibraryFaq = {
  question: string;
  answer: string;
};

export type LibraryArticle = {
  slug: string;
  sourcePage: number;
  section: string;
  title: string;
  summary: string;
  status: "published" | "coming-soon";
  topics: string[];
  mskRelevant: boolean;
  sections: LibrarySection[];
  caveats: string[];
  faqs: LibraryFaq[];
};

export const libraryDisclaimer =
  "These library pages are original education notes for both patients and practitioners at Nguyen's Osteopathic Clinic. They are not prescribing advice, product endorsements, or a republication of any third-party training manual. Patients should check with a GP, pharmacist, or osteopath before starting supplements. Practitioners should use them as discussion prompts only within their regulated scope.";

export const libraryArticles = libraryData.articles as LibraryArticle[];

export function getLibraryArticle(slug: string): LibraryArticle | undefined {
  return libraryArticles.find((article) => article.slug === slug);
}

export function getAllLibrarySlugs(): string[] {
  return libraryArticles.map((article) => article.slug);
}

export function getLibraryArticleCount(): number {
  return libraryArticles.length;
}

export function getLibraryArticlesBySection(): {
  section: string;
  label: string;
  articles: LibraryArticle[];
}[] {
  const order = [
    "front-matter",
    "contents",
    "products-a-z",
    "ailments",
    "sports-weight-loss",
    "sports",
    "weight-loss",
    "reference",
    "forms",
  ];
  const labels: Record<string, string> = {
    "front-matter": "Start here",
    contents: "Contents",
    "products-a-z": "Ingredients & themes A–Z",
    ailments: "Wellness themes",
    "sports-weight-loss": "Sports & weight themes",
    sports: "Sports",
    "weight-loss": "Weight themes",
    reference: "Reference",
    forms: "Forms & labels",
  };

  const bySection = new Map<string, LibraryArticle[]>();
  for (const article of libraryArticles) {
    const key = article.section || "general";
    const list = bySection.get(key) ?? [];
    list.push(article);
    bySection.set(key, list);
  }

  const groups = order
    .filter((key) => bySection.has(key))
    .map((key) => ({
      section: key,
      label: labels[key] ?? key,
      articles: bySection.get(key)!,
    }));

  for (const [key, articles] of bySection) {
    if (!order.includes(key)) {
      groups.push({ section: key, label: key, articles });
    }
  }
  return groups;
}
